'use strict';

// MODULES //

var tape = require( 'tape' );
var array = require( '@stdlib/ndarray/array' );
var Float64Array = require( '@stdlib/array/float64' );
var Model = require( './../lib/model.js' );


// FUNCTIONS //

/**
* Returns a model configured to use the modified Huber loss function with a constant learning rate and no regularization.
*
* @private
* @param {number} eta - learning rate
* @returns {Model} model instance
*/
function createModel( eta ) {
	return new Model( 1, {
		'lambda': 0.0,
		'learningRate': [ 'constant', eta ],
		'loss': 'modifiedHuber',
		'intercept': false
	});
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Model, 'function', 'main export is a function' );
	t.end();
});

tape( 'the modified Huber loss update includes a `2` factor when `-1 <= y*f(x) < 1` (see stdlib-js/stdlib#13111)', function test( t ) {
	var expected;
	var model;
	var eta;
	var x;

	eta = 0.1;
	model = createModel( eta );

	// Force `d = y*f(x) = 0.3`, landing in the quadratically smoothed region:
	model._weights[ 0 ] = 0.3; // eslint-disable-line no-underscore-dangle
	x = array( new Float64Array( [ 1.0 ] ) );

	model.update( x, 1 );

	// Expected update: w += 2*eta*( y - d*y ) = 0.3 + 2*0.1*( 1 - 0.3*1 ):
	expected = 0.3 + ( 2.0*eta*( 1.0-(0.3*1.0) ) );
	t.strictEqual( model._weights[ 0 ], expected, 'includes the `2` factor in the update' ); // eslint-disable-line no-underscore-dangle
	t.end();
});

tape( 'the modified Huber loss does not update the model weight vector when `y*f(x) >= 1`', function test( t ) {
	var model;
	var eta;
	var x;

	eta = 0.1;
	model = createModel( eta );

	// Force `d = y*f(x) = 2.0`, past the margin, where the gradient is zero:
	model._weights[ 0 ] = 2.0; // eslint-disable-line no-underscore-dangle
	x = array( new Float64Array( [ 1.0 ] ) );

	model.update( x, 1 );

	t.strictEqual( model._weights[ 0 ], 2.0, 'leaves the model weight vector unchanged' ); // eslint-disable-line no-underscore-dangle
	t.end();
});

tape( 'the modified Huber loss update matches the existing `-4*eta*y` branch when `y*f(x) < -1`', function test( t ) {
	var expected;
	var model;
	var eta;
	var x;

	eta = 0.1;
	model = createModel( eta );

	// Force `d = y*f(x) = -2.0`:
	model._weights[ 0 ] = -2.0; // eslint-disable-line no-underscore-dangle
	x = array( new Float64Array( [ 1.0 ] ) );

	model.update( x, 1 );

	expected = -2.0 + ( 4.0*eta*1.0 );
	t.strictEqual( model._weights[ 0 ], expected, 'applies the unchanged `d < -1` branch' ); // eslint-disable-line no-underscore-dangle
	t.end();
});
